const BRAND_ICONS: Record<string, (props: { className?: string }) => React.ReactNode> = {
  Spotify: SpotifyIcon,
  "Apple Music": AppleMusicIcon,
  Audiomack: AudiomackIcon,
  Instagram: InstagramIcon,
  TikTok: TikTokIcon,
  Facebook: FacebookIcon,
};

export default function Footer() {
  const [email, setEmail] = useState("");
  const [done, setDone] = useState(false);

  return (
    <footer className="relative border-t border-white/10 bg-[#08090a]">
      <div className="max-w-7xl mx-auto px-5 md:px-10 pt-16 md:pt-20 pb-8">
        {/* Newsletter strip */}
        <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-8 pb-14 border-b border-white/10">
          <div>
            <h3 className="font-display text-3xl md:text-4xl uppercase leading-[0.95]">
              First access.
              <br />
              <span className="text-white/30">First sound.</span>
            </h3>
          </div>
          {done ? (
            <p className="border border-white/15 px-5 py-3.5 text-sm text-white/70 md:min-w-[320px]">
              You&apos;re in. Welcome to the inner circle.
            </p>
          ) : (
            <form
              onSubmit={(e) => {
                e.preventDefault();
                if (email.trim()) setDone(true);
              }}
              className="flex w-full md:w-auto md:min-w-[320px]"
            >
              <input
                type="email"
                required
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                placeholder="your@email.com"
                className="min-w-0 flex-1 h-12 px-4 bg-transparent border border-white/15 text-sm text-white placeholder:text-white/25 outline-none focus:border-white/60 transition-colors"
              />
              <button
                type="submit"
                className="shrink-0 px-6 bg-white text-black text-[10px] font-bold tracking-[0.3em] uppercase hover:bg-white/80 transition-colors"
              >
                Join
              </button>
            </form>
          )}
        </div>

        {/* Link columns */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-10 py-14">
          <div className="col-span-2 md:col-span-1">
            <div className="w-14 h-14 relative mb-4">
              <Image
                src="/whalesails/wsr-logo.png"
                alt="Whalesails Records"
                fill
                className="object-contain"
                sizes="56px"
              />
            </div>
            <p className="font-display text-xl tracking-[0.15em] uppercase mb-2">
              Whalesails
              <br />
              Records LTD
            </p>
            <p className="text-xs text-white/35 leading-relaxed max-w-[240px]">
              Cinematic sound, timeless vision and premium artistry.
            </p>
          </div>

          <div>
            <p className="text-[10px] font-mono tracking-[0.35em] text-white/40 uppercase mb-5">
              Explore
            </p>
            <ul className="space-y-3">
              {NAV_ITEMS.filter((n) => n.href !== "/").map((item) => (
                <li key={item.href}>
                  <Link
                    href={item.href}
                    className="text-sm text-white/50 hover:text-white transition-colors"
                  >
                    {item.label}
                  </Link>
                </li>
              ))}
            </ul>
          </div>

          <div>
            <p className="text-[10px] font-mono tracking-[0.35em] text-white/40 uppercase mb-5">
              Services
            </p>
            <ul className="space-y-3">
              {SERVICES.map((s) => (
                <li key={s.num}>
                  <Link
                    href="/services"
                    className="text-sm text-white/50 hover:text-white transition-colors"
                  >
                    {s.title}
                  </Link>
                </li>
              ))}
            </ul>
          </div>

          <div>
            <p className="text-[10px] font-mono tracking-[0.35em] text-white/40 uppercase mb-5">
              Connect
            </p>
            <ul className="space-y-4">
              <li>
                <a
                  href={`mailto:${CONTACT.email}`}
                  className="flex items-center gap-3 text-sm text-white/50 hover:text-white transition-colors"
                >
                  <Mail className="w-4 h-4 shrink-0" />
                  {CONTACT.email}
                </a>
              </li>
              <li className="flex items-center gap-3 text-sm text-white/50">
                <MapPin className="w-4 h-4 shrink-0" />
                {CONTACT.location}
              </li>
            </ul>
            <div className="flex flex-wrap gap-3 mt-6">
              {PLATFORMS.map((p) => {
                const Icon = BRAND_ICONS[p.name];
                return (
                  <a
                    key={p.name}
                    href={p.url}
                    target="_blank"
                    rel="noopener noreferrer"
                    title={p.name}
                    aria-label={p.name}
                    className="flex items-center justify-center w-10 h-10 border border-white/10 text-white/50 hover:bg-white hover:text-black hover:border-white transition-all duration-300"
                  >
                    <Icon className="w-4 h-4" />
                  </a>
                );
              })}
            </div>
          </div>
        </div>

        {/* Bottom legal bar */}
        <div className="flex flex-col md:flex-row items-center justify-between gap-4 py-6 border-t border-white/5">
          <p className="text-[10px] font-mono tracking-[0.2em] text-white/25 uppercase">
            © {new Date().getFullYear()} Whalesails Records LTD. All rights
            reserved.
          </p>
          <div className="flex items-center gap-6 text-[10px] font-mono tracking-[0.2em] text-white/25 uppercase">
            <Link href="/label" className="hover:text-white/60 transition-colors">
              Privacy
            </Link>
            <Link href="/label" className="hover:text-white/60 transition-colors">
              Terms
            </Link>
            <Link href="/contact" className="hover:text-white/60 transition-colors">
              Press Kit
            </Link>
          </div>
        </div>
      </div>
    </footer>
  );
}